'use strict';

const { RESOLVE_TIMEOUT_MS, SSE_URL_MARKER } = require('./constants');
const { MediaDownloaderError, ERROR_CODES } = require('./errors');

/**
 * Some links the API hands back are not files — they are Server-Sent Event
 * streams that report encoding progress and only reveal the real file URL in
 * their final event. Fetching one as if it were a video yields `text/event-stream`
 * text instead of bytes, so it has to be drained first.
 *
 * Progress events look like:
 *   data:{"progress":50,"status":"in_progress",...}
 * and the last event carries the payload we want:
 *   data:{"download_url":"https://.../download?...","file_info":{...}}
 */

const USER_AGENT = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36';

/** True when a URL streams progress events rather than the file itself. */
function needsResolve(url) {
  return typeof url === 'string' && url.includes(SSE_URL_MARKER);
}

/** Pull the last JSON object carrying a download_url out of an SSE body. */
function extractFromStream(text) {
  const events = text
    .split('\n')
    .filter((line) => line.startsWith('data:'))
    .map((line) => line.slice(5).trim());

  for (let i = events.length - 1; i >= 0; i -= 1) {
    let event;
    try {
      event = JSON.parse(events[i]);
    } catch {
      continue;
    }

    if (event.download_url) {
      return {
        url: event.download_url,
        // file_info gives us a trustworthy duration in seconds and a filename.
        duration: event.file_info?.duration ?? null,
        filename: event.file_info?.file_name ?? null,
        extension: event.file_info?.ext ?? null,
      };
    }

    if (event.status === 'error' || event.error) {
      throw new MediaDownloaderError(
        `Encoding failed: ${event.message || event.error}`,
        { code: ERROR_CODES.RESOLVE_FAILED }
      );
    }
  }

  return null;
}

/**
 * Turn a progress-stream link into a real file link.
 * Plain URLs pass straight through, so this is always safe to call.
 *
 * @param {string} url
 * @param {object} [options]
 * @param {number} [options.timeoutMs] Defaults to 180000 — encoding is slow.
 * @param {(progress: {percent: number, status: string}) => void} [options.onProgress]
 * @returns {Promise<{url: string, duration: number|null, filename: string|null}>}
 */
async function resolveUrl(url, options = {}) {
  if (!needsResolve(url)) return { url, duration: null, filename: null };

  const timeoutMs = options.timeoutMs || RESOLVE_TIMEOUT_MS;

  let response;
  try {
    response = await fetch(url, {
      headers: { 'User-Agent': options.userAgent || USER_AGENT, Accept: 'text/event-stream' },
      signal: AbortSignal.timeout(timeoutMs),
    });
  } catch (cause) {
    throw new MediaDownloaderError(`Could not read progress stream: ${cause.message}`, {
      code: ERROR_CODES.RESOLVE_FAILED,
    });
  }

  if (!response.ok || !response.body) {
    throw new MediaDownloaderError(`Progress stream returned HTTP ${response.status}`, {
      code: ERROR_CODES.RESOLVE_FAILED,
      status: response.status,
    });
  }

  let buffer = '';
  let lastPercent = -1;

  for await (const chunk of response.body) {
    buffer += Buffer.from(chunk).toString('utf8');

    if (options.onProgress) {
      const events = buffer.split('\n').filter((line) => line.startsWith('data:'));
      const latest = events[events.length - 1];
      if (latest) {
        try {
          const parsed = JSON.parse(latest.slice(5));
          if (typeof parsed.progress === 'number' && parsed.progress !== lastPercent) {
            lastPercent = parsed.progress;
            options.onProgress({ percent: parsed.progress, status: parsed.status || '' });
          }
        } catch {
          // Partial event, wait for more data.
        }
      }
    }
  }

  const resolved = extractFromStream(buffer);

  if (!resolved) {
    throw new MediaDownloaderError('Progress stream ended without a download URL', {
      code: ERROR_CODES.RESOLVE_FAILED,
    });
  }

  return resolved;
}

module.exports = { resolveUrl, needsResolve, extractFromStream };
